Lemmatheca.MathematicalLogic.InterpretingTheories.InterpretationData.realize_graphSentence.{u, v, u', v', w}
  {L : FirstOrder.Language} {K : FirstOrder.Language}
  (I : Lemmatheca.MathematicalLogic.InterpretingTheories.InterpretationData L K) {M : Type w} [K.Structure M] {n : ℕ}
  (f : L.Functions n) :
  M ⊨ I.graphSentence f ↔
    ∀ (x : Fin n → M),
      (∀ (i : Fin n), I.domain.Realize fun x_1 => x i) → ∃! y, (I.guardedGraph f).Realize (Sum.elim x fun x => y)
